142|// Returns true if line has only space characters, else false.
143|static bool is_blank(cmark_strbuf *s, bufsize_t offset) {
144|  while (offset < s->size) {
145|    switch (s->ptr[offset]) {
146|    case '\r':
147|    case '\n':
148|      return true;
149|    case ' ':
150|      offset++;
151|      break;
152|    case '\t':
153|      offset++;
154|      break;
155|    default:
156|      return false;
157|    }
158|  }
159|
160|  return true;
161|}
