401|// Walk through node and all children, recursively, parsing
402|// string content into inline content where appropriate.
403|static void process_inlines(cmark_mem *mem, cmark_node *root,
404|                            cmark_reference_map *refmap, int options) {
405|  cmark_iter *iter = cmark_iter_new(root);
406|  cmark_node *cur;
407|  cmark_event_type ev_type;
408|
409|  while ((ev_type = cmark_iter_next(iter)) != CMARK_EVENT_DONE) {
410|    cur = cmark_iter_get_node(iter);
411|    if (ev_type == CMARK_EVENT_ENTER) {
412|      if (contains_inlines(S_type(cur))) {
413|        cmark_parse_inlines(mem, cur, refmap, options);
414|        mem->free(cur->data);
415|        cur->data = NULL;
416|        cur->len = 0;
417|      }
418|    }
419|  }
420|
421|  cmark_iter_free(iter);
422|}
