513|// Return 1 if list item belongs in list, else 0.
514|static int lists_match(cmark_list *list_data, cmark_list *item_data) {
515|  return (list_data->list_type == item_data->list_type &&
516|          list_data->delimiter == item_data->delimiter &&
517|          // list_data->marker_offset == item_data.marker_offset &&
518|          list_data->bullet_char == item_data->bullet_char);
