779|static bool parse_block_quote_prefix(cmark_parser *parser, cmark_chunk *input) {
780|  bool res = false;
781|  bufsize_t matched = 0;
782|
783|  matched =
784|      parser->indent <= 3 && peek_at(input, parser->first_nonspace) == '>';
785|  if (matched) {
786|
787|    S_advance_offset(parser, input, parser->indent + 1, true);
788|
789|    if (S_is_space_or_tab(peek_at(input, parser->offset))) {
790|      S_advance_offset(parser, input, 1, true);
791|    }
792|
793|    res = true;
794|  }
795|  return res;
