1190|  // If the last line processed belonged to a paragraph node,
1191|  // and we didn't match all of the line prefixes for the open containers,
1192|  // and we didn't start any new containers,
1193|  // and the line isn't blank,
1194|  // then treat this as a "lazy continuation line" and add it to
1195|  // the open paragraph.
1196|  if (parser->current != last_matched_container &&
1197|      container == last_matched_container && !parser->blank &&
1198|      S_type(parser->current) == CMARK_NODE_PARAGRAPH) {
1199|    add_line(input, parser);
1200|  } else { // not a lazy continuation
1201|    // Finalize any blocks that were not matched and set cur to container:
1202|    while (parser->current != last_matched_container) {
1203|      parser->current = finalize(parser, parser->current);
1204|      assert(parser->current != NULL);
1205|    }
1206|
1207|    if (S_type(container) == CMARK_NODE_CODE_BLOCK) {
1208|      add_line(input, parser);
1209|    } else if (S_type(container) == CMARK_NODE_HTML_BLOCK) {
1210|      add_line(input, parser);
1211|
1212|      int matches_end_condition;
1213|      switch (container->as.html_block_type) {
1214|      case 1:
1215|        // </script>, </style>, </textarea>, </pre>
1216|        matches_end_condition =
1217|            scan_html_block_end_1(input, parser->first_nonspace);
1218|        break;
1219|      case 2:
1220|        // -->
1221|        matches_end_condition =
1222|            scan_html_block_end_2(input, parser->first_nonspace);
1223|        break;
1224|      case 3:
1225|        // ?>
1226|        matches_end_condition =
1227|            scan_html_block_end_3(input, parser->first_nonspace);
1228|        break;
1229|      case 4:
1230|        // >
1231|        matches_end_condition =
1232|            scan_html_block_end_4(input, parser->first_nonspace);
1233|        break;
1234|      case 5:
1235|        // ]]>
1236|        matches_end_condition =
1237|            scan_html_block_end_5(input, parser->first_nonspace);
1238|        break;
1239|      default:
1240|        matches_end_condition = 0;
1241|        break;
1242|      }
1243|
1244|      if (matches_end_condition) {
1245|        container = finalize(parser, container);
1246|        assert(parser->current != NULL);
1247|      }
1248|    } else if (parser->blank) {
1249|      // ??? do nothing
1250|    } else if (accepts_lines(S_type(container))) {
1251|      if (S_type(container) == CMARK_NODE_HEADING &&
