375|// Add a node as child of another.  Return pointer to child.
376|static cmark_node *add_child(cmark_parser *parser, cmark_node *parent,
377|                             cmark_node_type block_type, int start_column) {
378|  assert(parent);
379|
380|  // if 'parent' isn't the kind of node that can accept this child,
381|  // then back up til we hit a node that can.
382|  while (!can_contain(S_type(parent), block_type)) {
383|    parent = finalize(parser, parent);
384|  }
385|
386|  cmark_node *child =
387|      make_block(parser->mem, block_type, parser->line_number, start_column);
388|  child->parent = parent;
389|
390|  if (parent->last_child) {
391|    parent->last_child->next = child;
392|    child->prev = parent->last_child;
393|  } else {
394|    parent->first_child = child;
395|    child->prev = NULL;
396|  }
397|  parent->last_child = child;
398|  return child;
