1158|static void add_text_to_container(cmark_parser *parser, cmark_node *container,
1159|                                  cmark_node *last_matched_container,
1160|                                  cmark_chunk *input) {
1161|  cmark_node *tmp;
1162|  // what remains at parser->offset is a text line.  add the text to the
1163|  // appropriate container.
1164|
1165|  S_find_first_nonspace(parser, input);
1166|
1167|  if (parser->blank && container->last_child)
1168|    S_set_last_line_blank(container->last_child, true);
1169|
1170|  // block quote lines are never blank as they start with >
1171|  // and we don't count blanks in fenced code for purposes of tight/loose
1172|  // lists or breaking out of lists.  we also don't set last_line_blank
1173|  // on an empty list item.
1174|  const cmark_node_type ctype = S_type(container);
1175|  const bool last_line_blank =
1176|      (parser->blank && ctype != CMARK_NODE_BLOCK_QUOTE &&
1177|       ctype != CMARK_NODE_HEADING && ctype != CMARK_NODE_THEMATIC_BREAK &&
1178|       !(ctype == CMARK_NODE_CODE_BLOCK && container->as.code.fenced) &&
1179|       !(ctype == CMARK_NODE_ITEM && container->first_child == NULL &&
1180|         container->start_line == parser->line_number));
1181|
1182|  S_set_last_line_blank(container, last_line_blank);
1183|
1184|  tmp = container;
1185|  while (tmp->parent) {
1186|    S_set_last_line_blank(tmp->parent, false);
1187|    tmp = tmp->parent;
1188|  }
1189|
1190|  // If the last line processed belonged to a paragraph node,
1191|  // and we didn't match all of the line prefixes for the open containers,
1192|  // and we didn't start any new containers,
1193|  // and the line isn't blank,
1194|  // then treat this as a "lazy continuation line" and add it to
1195|  // the open paragraph.
1196|  if (parser->current != last_matched_container &&
1197|      container == last_matched_container && !parser->blank &&
1198|      S_type(parser->current) == CMARK_NODE_PARAGRAPH) {
1199|    add_line(input, parser);
1200|  } else { // not a lazy continuation
1201|    // Finalize any blocks that were not matched and set cur to container:
1202|    while (parser->current != last_matched_container) {
1203|      parser->current = finalize(parser, parser->current);
1204|      assert(parser->current != NULL);
1205|    }
1206|
1207|    if (S_type(container) == CMARK_NODE_CODE_BLOCK) {
1208|      add_line(input, parser);
1209|    } else if (S_type(container) == CMARK_NODE_HTML_BLOCK) {
1210|      add_line(input, parser);
1211|
1212|      int matches_end_condition;
1213|      switch (container->as.html_block_type) {
1214|      case 1:
1215|        // </script>, </style>, </textarea>, </pre>
1216|        matches_end_condition =
1217|            scan_html_block_end_1(input, parser->first_nonspace);
1218|        break;
1219|      case 2:
1220|        // -->
1221|        matches_end_condition =
1222|            scan_html_block_end_2(input, parser->first_nonspace);
1223|        break;
1224|      case 3:
1225|        // ?>
1226|        matches_end_condition =
1227|            scan_html_block_end_3(input, parser->first_nonspace);
1228|        break;
1229|      case 4:
1230|        // >
1231|        matches_end_condition =
1232|            scan_html_block_end_4(input, parser->first_nonspace);
1233|        break;
1234|      case 5:
1235|        // ]]>
1236|        matches_end_condition =
1237|            scan_html_block_end_5(input, parser->first_nonspace);
1238|        break;
1239|      default:
1240|        matches_end_condition = 0;
1241|        break;
1242|      }
1243|
1244|      if (matches_end_condition) {
1245|        container = finalize(parser, container);
1246|        assert(parser->current != NULL);
1247|      }
1248|    } else if (parser->blank) {
1249|      // ??? do nothing
1250|    } else if (accepts_lines(S_type(container))) {
1251|      if (S_type(container) == CMARK_NODE_HEADING &&
1252|          container->as.heading.setext == false) {
1253|        chop_trailing_hashtags(input);
1254|      }
1255|      S_advance_offset(parser, input, parser->first_nonspace - parser->offset,
1256|                       false);
1257|      add_line(input, parser);
1258|    } else {
1259|      // create paragraph container for line
1260|      container = add_child(parser, container, CMARK_NODE_PARAGRAPH,
1261|                            parser->first_nonspace + 1);
1262|      S_advance_offset(parser, input, parser->first_nonspace - parser->offset,
1263|                       false);
1264|      add_line(input, parser);
1265|    }
1266|
1267|    parser->current = container;
1268|  }
