1271|/* See http://spec.commonmark.org/0.24/#phase-1-block-structure */
1272|static void S_process_line(cmark_parser *parser, const unsigned char *buffer,
1273|                           bufsize_t bytes) {
1274|  cmark_node *last_matched_container;
1275|  bool all_matched = true;
1276|  cmark_node *container;
1277|  cmark_chunk input;
1278|
1279|  if (parser->options & CMARK_OPT_VALIDATE_UTF8)
1280|    cmark_utf8proc_check(&parser->curline, buffer, bytes);
1281|  else
1282|    cmark_strbuf_put(&parser->curline, buffer, bytes);
1283|
1284|  bytes = parser->curline.size;
1285|
1286|  // ensure line ends with a newline:
1287|  if (bytes == 0 || !S_is_line_end_char(parser->curline.ptr[bytes - 1]))
1288|    cmark_strbuf_putc(&parser->curline, '\n');
1289|
1290|  parser->offset = 0;
1291|  parser->column = 0;
1292|  parser->first_nonspace = 0;
1293|  parser->first_nonspace_column = 0;
1294|  parser->thematic_break_kill_pos = 0;
1295|  parser->indent = 0;
1296|  parser->blank = false;
1297|  parser->partially_consumed_tab = false;
1298|
1299|  input.data = parser->curline.ptr;
1300|  input.len = parser->curline.size;
1301|
1302|  parser->line_number++;
1303|
1304|  last_matched_container = check_open_blocks(parser, &input, &all_matched);
1305|
1306|  if (!last_matched_container)
1307|    goto finished;
1308|
1309|  container = last_matched_container;
1310|
1311|  open_new_blocks(parser, &container, &input, all_matched);
1312|
1313|  add_text_to_container(parser, container, last_matched_container, &input);
1314|
1315|finished:
1316|  parser->last_line_length = input.len;
1317|  if (parser->last_line_length &&
1318|      input.data[parser->last_line_length - 1] == '\n')
1319|    parser->last_line_length -= 1;
1320|  if (parser->last_line_length &&
1321|      input.data[parser->last_line_length - 1] == '\r')
1322|    parser->last_line_length -= 1;
1323|
1324|  cmark_strbuf_clear(&parser->curline);
1325|}
