1327|cmark_node *cmark_parser_finish(cmark_parser *parser) {
1328|  if (parser->linebuf.size) {
1329|    S_process_line(parser, parser->linebuf.ptr, parser->linebuf.size);
1330|    cmark_strbuf_clear(&parser->linebuf);
1331|  }
1332|
1333|  finalize_document(parser);
1334|
1335|  cmark_consolidate_text_nodes(parser->root);
1336|
1337|  cmark_strbuf_free(&parser->curline);
1338|
1339|#if CMARK_DEBUG_NODES
1340|  if (cmark_node_check(parser->root, stderr)) {
1341|    abort();
1342|  }
1343|#endif
1344|  return parser->root;
