576|static void S_parser_feed(cmark_parser *parser, const unsigned char *buffer,
577|                          size_t len, bool eof) {
578|  const unsigned char *end = buffer + len;
579|  static const uint8_t repl[] = {239, 191, 189};
580|
581|  if (len > UINT_MAX - parser->total_size)
582|    parser->total_size = UINT_MAX;
583|  else
584|    parser->total_size += (int)len;
585|
586|  // Skip UTF-8 BOM if present; see #334
587|  if (parser->line_number == 0 && parser->column == 0 && len >= 3 &&
588|      *buffer == 0xEF && *(buffer + 1) == 0xBB &&
589|      *(buffer + 2) == 0xBF) {
590|    buffer += 3;
591|  } else if (parser->last_buffer_ended_with_cr && *buffer == '\n') {
592|    // skip NL if last buffer ended with CR ; see #117
593|    buffer++;
594|  }
595|
596|  parser->last_buffer_ended_with_cr = false;
597|  while (buffer < end) {
598|    const unsigned char *eol;
599|    bufsize_t chunk_len;
600|    bool process = false;
601|    for (eol = buffer; eol < end; ++eol) {
602|      if (S_is_line_end_char(*eol)) {
603|        process = true;
604|        break;
605|      }
606|      if (*eol == '\0' && eol < end) {
607|        break;
608|      }
609|    }
610|    if (eol >= end && eof) {
611|      process = true;
612|    }
613|
614|    chunk_len = (eol - buffer);
615|    if (process) {
616|      if (parser->linebuf.size > 0) {
617|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
618|        S_process_line(parser, parser->linebuf.ptr, parser->linebuf.size);
619|        cmark_strbuf_clear(&parser->linebuf);
620|      } else {
621|        S_process_line(parser, buffer, chunk_len);
622|      }
623|    } else {
624|      if (eol < end && *eol == '\0') {
625|        // omit NULL byte
626|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
627|        // add replacement character
628|        cmark_strbuf_put(&parser->linebuf, repl, 3);
629|      } else {
630|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
631|      }
632|    }
633|
634|    buffer += chunk_len;
635|    if (buffer < end) {
636|      if (*buffer == '\0') {
637|        // skip over NULL
638|        buffer++;
639|      } else {
640|        // skip over line ending characters
641|        if (*buffer == '\r') {
642|          buffer++;
643|          if (buffer == end)
644|            parser->last_buffer_ended_with_cr = true;
645|        }
646|        if (buffer < end && *buffer == '\n')
647|          buffer++;
648|      }
649|    }
650|  }
651|}

57|int houdini_escape_href(cmark_strbuf *ob, const uint8_t *src, bufsize_t size) {
58|  static const uint8_t hex_chars[] = "0123456789ABCDEF";
59|  bufsize_t i = 0, org;
60|  uint8_t hex_str[3];
61|
62|  hex_str[0] = '%';
63|
64|  while (i < size) {
65|    org = i;
66|    while (i < size && HREF_SAFE[src[i]] != 0)
67|      i++;
68|
69|    if (likely(i > org))
70|      cmark_strbuf_put(ob, src + org, i - org);
71|
72|    /* escaping */
73|    if (i >= size)
74|      break;
75|
76|    switch (src[i]) {
77|    /* amp appears all the time in URLs, but needs
78|     * HTML-entity escaping to be inside an href */
79|    case '&':
80|      cmark_strbuf_puts(ob, "&amp;");
81|      break;
82|
83|    /* the single quote is a valid URL character
84|     * according to the standard; it needs HTML
85|     * entity escaping too */
86|    case '\'':
87|      cmark_strbuf_puts(ob, "&#x27;");
88|      break;
89|
90|/* the space can be escaped to %20 or a plus
91| * sign. we're going with the generic escape
92| * for now. the plus thing is more commonly seen
93| * when building GET strings */
94|#if 0
95|    case ' ':
96|      cmark_strbuf_putc(ob, '+');
97|      break;
98|#endif
99|
100|    /* every other character goes with a %XX escaping */
101|    default:
102|      hex_str[1] = hex_chars[(src[i] >> 4) & 0xF];
103|      hex_str[2] = hex_chars[src[i] & 0xF];
104|      cmark_strbuf_put(ob, hex_str, 3);
105|    }
106|
107|    i++;
108|  }
109|
110|  return 1;
111|}

