20|static inline void outc(cmark_renderer *renderer, cmark_escaping escape,
21|                        int32_t c, unsigned char nextc) {
22|  if (escape == LITERAL) {
23|    cmark_render_code_point(renderer, c);
24|    return;
25|  }
26|
27|  switch (c) {
28|  case 123: // '{'
29|  case 125: // '}'
30|  case 35:  // '#'
31|  case 37:  // '%'
32|  case 38:  // '&'
33|    cmark_render_ascii(renderer, "\\");
34|    cmark_render_code_point(renderer, c);
35|    break;
36|  case 36: // '$'
37|  case 95: // '_'
38|    if (escape == NORMAL) {
39|      cmark_render_ascii(renderer, "\\");
40|    }
41|    cmark_render_code_point(renderer, c);
42|    break;
43|  case 45:             // '-'
44|    if (nextc == 45) { // prevent ligature
45|      cmark_render_ascii(renderer, "-{}");
46|    } else {
47|      cmark_render_ascii(renderer, "-");
48|    }
49|    break;
50|  case 126: // '~'
51|    if (escape == NORMAL) {
52|      cmark_render_ascii(renderer, "\\textasciitilde{}");
53|    } else {
54|      cmark_render_code_point(renderer, c);
55|    }
56|    break;
57|  case 94: // '^'
58|    cmark_render_ascii(renderer, "\\^{}");
59|    break;
60|  case 92: // '\\'
61|    if (escape == URL) {
62|      // / acts as path sep even on windows:
63|      cmark_render_ascii(renderer, "/");
64|    } else {
65|      cmark_render_ascii(renderer, "\\textbackslash{}");
66|    }
67|    break;
68|  case 124: // '|'
69|    cmark_render_ascii(renderer, "\\textbar{}");
70|    break;
71|  case 60: // '<'
72|    cmark_render_ascii(renderer, "\\textless{}");
73|    break;
74|  case 62: // '>'
75|    cmark_render_ascii(renderer, "\\textgreater{}");
76|    break;
77|  case 91: // '['
78|  case 93: // ']'
79|    cmark_render_ascii(renderer, "{");
80|    cmark_render_code_point(renderer, c);
81|    cmark_render_ascii(renderer, "}");
82|    break;
83|  case 34: // '"'
84|    cmark_render_ascii(renderer, "\\textquotedbl{}");
85|    // requires \usepackage[T1]{fontenc}
86|    break;
87|  case 39: // '\''
88|    cmark_render_ascii(renderer, "\\textquotesingle{}");
89|    // requires \usepackage{textcomp}
90|    break;
91|  case 160: // nbsp
92|    cmark_render_ascii(renderer, "~");
93|    break;
94|  case 8230: // hellip
95|    cmark_render_ascii(renderer, "\\ldots{}");
96|    break;
97|  case 8216: // lsquo
98|    if (escape == NORMAL) {
99|      cmark_render_ascii(renderer, "`");
100|    } else {
101|      cmark_render_code_point(renderer, c);
102|    }
103|    break;
104|  case 8217: // rsquo
105|    if (escape == NORMAL) {
106|      cmark_render_ascii(renderer, "\'");
107|    } else {
108|      cmark_render_code_point(renderer, c);
109|    }
110|    break;
111|  case 8220: // ldquo
112|    if (escape == NORMAL) {
113|      cmark_render_ascii(renderer, "``");
114|    } else {
115|      cmark_render_code_point(renderer, c);
116|    }
117|    break;
118|  case 8221: // rdquo
119|    if (escape == NORMAL) {
120|      cmark_render_ascii(renderer, "''");
121|    } else {
122|      cmark_render_code_point(renderer, c);
123|    }
124|    break;
125|  case 8212: // emdash
126|    if (escape == NORMAL) {
127|      cmark_render_ascii(renderer, "---");
128|    } else {
129|      cmark_render_code_point(renderer, c);
130|    }
131|    break;
132|  case 8211: // endash
133|    if (escape == NORMAL) {
134|      cmark_render_ascii(renderer, "--");
135|    } else {
136|      cmark_render_code_point(renderer, c);
137|    }
138|    break;
139|  default:
140|    cmark_render_code_point(renderer, c);
141|  }
142|}

24|static inline void outc(cmark_renderer *renderer, cmark_escaping escape,
25|                        int32_t c, unsigned char nextc) {
26|  bool needs_escaping = false;
27|  bool follows_digit =
28|      renderer->buffer->size > 0 &&
29|      cmark_isdigit(renderer->buffer->ptr[renderer->buffer->size - 1]);
30|  char encoded[ENCODED_SIZE];
31|  int options = renderer->options;
32|
33|  needs_escaping =
34|      c < 0x80 && escape != LITERAL &&
35|      ((escape == NORMAL &&
36|        (c < 0x20 ||
37|         c == '*' || c == '_' || c == '[' || c == ']' || c == '#' || c == '<' ||
38|         c == '>' || c == '\\' || c == '`' ||
39|	 (c == '!' && (!nextc || nextc == '[')) ||
40|         (c == '&' && cmark_isalpha(nextc)) || (c == '!' && nextc == '[') ||
41|         ((CMARK_OPT_SMART & options) &&
42|            ((c == '-' && nextc == '-') ||
43|             (c == '.' && nextc == '.') ||
44|             c == '"' || c == '\'')) ||
45|         (renderer->begin_content && (c == '-' || c == '+' || c == '=') &&
46|          // begin_content doesn't get set to false til we've passed digits
47|          // at the beginning of line, so...
48|          !follows_digit) ||
49|         (renderer->begin_content && (c == '.' || c == ')') && follows_digit &&
50|          (nextc == 0 || cmark_isspace(nextc))))) ||
51|       (escape == URL &&
52|        (c == '`' || c == '<' || c == '>' || cmark_isspace(c) || c == '\\' ||
53|         c == ')' || c == '(')) ||
54|       (escape == TITLE &&
55|        (c == '`' || c == '<' || c == '>' || c == '"' || c == '\\')));
56|
57|  if (needs_escaping) {
58|    if (escape == URL && cmark_isspace(c)) {
59|      // use percent encoding for spaces
60|      snprintf(encoded, ENCODED_SIZE, "%%%2X", c);
61|      cmark_strbuf_puts(renderer->buffer, encoded);
62|      renderer->column += 3;
63|    } else if (cmark_ispunct(c)) {
64|      cmark_render_ascii(renderer, "\\");
65|      cmark_render_code_point(renderer, c);
66|    } else { // render as entity
67|      snprintf(encoded, ENCODED_SIZE, "&#%d;", c);
68|      cmark_strbuf_puts(renderer->buffer, encoded);
69|      renderer->column += (int)strlen(encoded);
70|    }
71|  } else {
72|    cmark_render_code_point(renderer, c);
73|  }
74|}

